            let cleaned = one_line(&raw, OVERVIEW_MAX_CHARS);
            if cleaned.is_empty() {
                fallback_overview(&selected.entries)
            } else {
                cleaned
            }
        };

        // Enforce the bound unconditionally, whatever path produced the text.
        let overview = clip(&overview, OVERVIEW_MAX_CHARS);

        Digest {
            // `requires len(in1.date) == 10` gives `ensures len(date) == 10`.
            date: info.date,
            overview,
            entries: selected.entries,
            considered: selected.considered,
        }
    }
}

export!(Node);
